Turns a list of passcodes (for example, the lines of a `.ydk` file) into cards, 100 per request, and reports passcodes that don't exist.

```js
const BASE = 'https://godokaapi.duelistsunite.org'

async function getJson(path) {
  const res = await fetch(BASE + path)
  if (!res.ok) {
    const { error, message } = await res.json()
    throw new Error(`${res.status} ${error}: ${message}`)
  }
  return res.json()
}

export async function resolvePasscodes(passcodes) {
  const unique = [...new Set(passcodes)]
  const byPasscode = new Map()

  for (let i = 0; unique.length > i; i += 100) {
    const chunk = unique.slice(i, i + 100)
    const { cards } = await getJson(`/cards?id=${chunk.join(',')}&limit=100`)
    for (const card of cards) {
      byPasscode.set(card.idSearched, card)
      // Passcodes of the same card come back once: map the other requested ones too.
      for (const id of chunk) if ([card.id, ...card.alternateArts].includes(id)) byPasscode.set(id, card)
    }
  }

  const missing = unique.filter((id) => !byPasscode.has(id))
  return { byPasscode, missing }
}

const { byPasscode, missing } = await resolvePasscodes([26202165, 46986431, 14558127])
for (const [id, card] of byPasscode) console.log(id, card.name, card.humanReadableCardType)
if (missing.length) console.warn('Unknown passcodes:', missing)
